    'Handled' => 'برطرف شد',
    'Show what Rafoo handled (%d)' => 'نمایش مواردی که رفو برطرف کرد (%d)',
    'No problem was found on the tested pages.' => 'در صفحه‌های آزمایش‌شده هیچ مشکلی پیدا نشد.',
    'Blocks the page' => 'مانع باز شدن صفحه',
    'Fixed. Run again to confirm' => 'برطرف شد؛ برای اطمینان مانور را دوباره اجرا کنید',
    'On: %s' => 'در: %s',
